def main():
    assert len(SEATS) == 32, len(SEATS)
    items = []
    for name, role, task in SEATS:
        prompt = (GODSPEED
                  + f"\n# Target\nsouji round 46, seat {name} (role: {role}). Lane repo: {LANE}. "
                  + f"Your seat directory: {SEAT_ROOT}/{name}/ — all your outputs (report.md, receipts) go there.\n\n"
                  + "# Task\n" + task + "\n")
        items.append({"name": name, "role": role, "axes": ["calibration","operability","coverage"], "prompt": prompt})
    spec = {
        "wave": "souji-r46-w1",
        "milestone": "r46 frozen C1 tip landing-suite receipt, C2 r45-register-verifier selftest, C3 F4 restore-collision entry",
        "reportDir": ".ufo/waves/round-46/w1",
        "context": CONTEXT,
        "items": items,
    }
    out = pathlib.Path(f"{LANE}/.ufo/waves/round-46/w1-spec.json")
    out.write_text(json.dumps(spec, indent=1))
    roles = {}
    for _, role, _ in SEATS: roles[role] = roles.get(role, 0) + 1
    print("spec written:", out, "seats:", len(items), "roles:", roles)

if __name__ == "__main__":
    main()
